-- Generated by supabase/schemas/diff.sh from the schema files. Read it
-- before pushing: renames come out as drop + create, which loses data.

SET local check_function_bodies = off;

DROP VIEW "challans"."handled_by_names";

CREATE OR REPLACE FUNCTION challans.handler_suggestions()
  RETURNS TABLE (
    name text,
    uses integer
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform core.require_module_access('challans');

  return query
  with typed as (
    select c.handled_by_name as typed_name, count(*)::int as typed_uses
    from challans.challans c
    group by c.handled_by_name
  ),
  staff as (
    select e.name as typed_name, 0 as typed_uses
    from core.employees e
    where core.employee_status_as_of(e.id, challans.today()) = 'active'
      and not exists (select 1 from typed t where lower(t.typed_name) = lower(e.name))
  )
  select names.typed_name, names.typed_uses
  from (select * from typed union all select * from staff) names
  order by names.typed_uses desc, names.typed_name;
end;
$function$;

CREATE VIEW "challans"."handled_by_names" WITH (security_invoker=true) AS  SELECT name,
    uses
   FROM challans.handler_suggestions() handler_suggestions(name, uses);

revoke execute on function challans.handler_suggestions() from public, anon;
grant execute on function challans.handler_suggestions() to authenticated;

GRANT SELECT ON TABLE "challans"."handled_by_names" TO "authenticated";
